1. First, copy and paste the following code into a Swift file:

```swift
import Foundation

let homophones: [String: String] = [
    "their": "they're",
    "there": "there",
    "they're": "they are",
    "know": "no",
    "weigh": "weight",
    "too": "",
    "no": "not",
    "is": "is",
    "it's": "it is",
    "knot": "not",
    "aloud": "allowed",
    "right": "write",
    "butt": "but",
    "sum": "some",
    "eye": "I",
    "seams": "seems",
    "bee": "be",
    "yew": "you"
]

func correctHomophones(_ text: String) -> String {
    let words = text.components(separatedBy: CharacterSet.whitespacesAndNewlines.inverted)
    var correctedWords: [String] = []

    for word in words {
        if let correction = homophones[word.lowercased()] {
            correctedWords.append(correction)
        } else {
            correctedWords.append(word)
        }
    }

    return correctedWords.joined(separator: " ")
}

