  let ipVersion;
  if (inputData.sourceIP && inputData.destinationIP) {
    // Check if IP addresses are IPv6
    ipVersion = /^([0-9a-f:]{15}|[0-9]{1,3}\.[0-9]{1,3}(\.:[0-9]{1,3}){3})$/.test(inputData.sourceIP)
