 Here's an example of a simple decorator for Nest.js middleware that checks the `NODE_ENV` environment variable and calls the `next()` function if it equals to "production" (true), otherwise returns `false`.

```typescript
import { createParamDecorator, ExecutionContext } from '@nestjs/common';

export const CheckProductionEnvironment = () => {
  return createParamDecorator(
    (data: unknown, ctx: ExecutionContext) => {
      const req = ctx.switchToHttp().getRequest();
      const nodeEnv = process.env.NODE_ENV;

      if (nodeEnv === 'production') {
        return req; // continue processing the request if in production environment
      } else {
        return false; // return false if not in production environment
      }
    },
  );
};

export function ProductionMiddleware() {
  return function (ctx: ExecutionContext, next: Function) {
    const isProduction = CheckProductionEnvironment()(ctx);

    if (isProduction) {
      next();
    } else {
      throw new Error('Not allowed in non-production environment');
    }
  };
}
```

You can use this decorator as follows:

```typescript
@Module()
export class AppModule {
  @Controller()
  @UseGlobalPipes(ValidationPipe())
  @UseMiddleware(ProductionMiddleware())
  controller() {
    @Get()
    getHello(@Req() request): string {
      return request.app.get('hello');
    }
  }
}
```

The `CheckProductionEnvironment` decorator is used to get the request object from the context, and the `ProductionMiddleware` function wraps the `next()` function with the check for the production environment. If the environment is not production, the middleware throws an error.

