 To identify if a given sentence in Go contains a double negative, follow these steps:

1. Create a slice of specific negative words:

```go
negativeWords := []string{"am not", "is not", "are not", "have not", "has not", "had not", "do not", "does not", "did not", "can not", "could not", "shall not", "should not", "may not", "might not", "must not", "will not", "won't", "don't", "never", "no", "not", "none", "neither", "nor"}
```

2. Define a function `containsDoubleNegative` that accepts a single argument, `sentence` which is a string:

```go
func containsDoubleNegative(sentence string) bool {
    // Split the sentence into words
    words := strings.FieldsFunc(sentence, func(c rune) bool { return c == ' ' })

    for i := 0; i < len(words)-1; i++ {
        // Check if current word is a negative word
        if contains(negativeWords, words[i]) {
            // Check if next word is also a negative word or the word "not"
            if (i+1 < len(words)) && (contains(negativeWords, words[i+1]) || words[i+1] == "not") {
                return true
            }
        }
    }

    return false
}

// Helper function to check if an array contains a specific element
func contains(array []string, target string) bool {
    for _, v := range array {
        if v == target {
            return true
        }
    }
    return false
}
```

3. Test the function with your example sentence:

```go
func main() {
    sentence := "He isn't not worried about the coronavirus situation"
    if containsDoubleNegative(sentence) {
        fmt.Println("The given sentence contains a double negative.")
    } else {
        fmt.Println("The given sentence does not contain a double negative.")
    }
}
```

